import {
	View,
	TouchableOpacity,
	StyleSheet,
	ViewStyle,
	Text
} from 'react-native'
import { Gesture, GestureDetector } from 'react-native-gesture-handler'
import { MotiView } from 'moti'
import { Image } from 'expo-image'
import { getBlurhashFromUUID } from '@/utils/getBlurhashFromUUID'
import { APPEAR_DURATION } from '@/constants'
import { defineStyles } from '@/utils/defineStyles'
import Animated, {
	interpolateColor,
	runOnJS,
	SharedValue,
	useAnimatedStyle,
	useSharedValue,
	withSpring
} from 'react-native-reanimated'
import { useEffect } from 'react'
import { router } from 'expo-router'
import * as Haptics from 'expo-haptics'
import { colors, useTheme } from '@/theme'

const ANIMATION_SPRING_CONFIG = {
	duration: APPEAR_DURATION,
	dampingRatio: 1.25
}

type Organization = {
	id: string
	name: string
	logoUrl: string | null
}

type AppearingImageContainerProps = {
	animatedStyle: ViewStyle
	organization: Organization
}

type OrganizationProfileImageProps = {
	currentOrganization: Organization
	nextOrganization: Organization
	prevOrganization: Organization
	currentOrganizationIndex: number
	getWrappedIndex: (offset: number) => number
	setCurrentOrganizationIndex: (index: number) => void
	isShining: boolean
	backgroundAnimation: SharedValue<number>
	hasOnlyOneOrganization: boolean
}

const AppearingImageContainer = ({
	animatedStyle,
	organization
}: AppearingImageContainerProps) => {
	return (
		<Animated.View
			style={[styles.headerRightAppearingContainer, animatedStyle]}
		>
			<View style={styles.headerRightAppearingInitialContainer}>
				<Image
					key={`appearing-${organization.id}`}
					source={
						organization.logoUrl ?? {
							blurhash: getBlurhashFromUUID(organization.id)
						}
					}
					placeholder={{
						blurhash: getBlurhashFromUUID(organization.id)
					}}
					style={styles.headerRightImage}
				/>
				<Text style={styles.headerRightAppearingInitial}>
					{organization.name.slice(0, 1)}
				</Text>
			</View>
		</Animated.View>
	)
}

export const OrganizationProfileImage = ({
	currentOrganization,
	nextOrganization,
	prevOrganization,
	currentOrganizationIndex,
	getWrappedIndex,
	setCurrentOrganizationIndex,
	isShining,
	backgroundAnimation,
	hasOnlyOneOrganization
}: OrganizationProfileImageProps) => {
	const { theme } = useTheme()

	const profileImageTranslateY = useSharedValue(0)
	const nextImageScale = useSharedValue(0)
	const prevImageScale = useSharedValue(0)
	const isAnimating = useSharedValue(false)

	useEffect(() => {
		profileImageTranslateY.set(0)
		nextImageScale.set(0)
		prevImageScale.set(0)
		isAnimating.set(false)
	}, [
		currentOrganizationIndex,
		isAnimating,
		nextImageScale,
		prevImageScale,
		profileImageTranslateY
	])

	const currentImageAnimatedStyle = useAnimatedStyle(() => ({
		transform: [{ translateY: profileImageTranslateY.get() }]
	}))

	const prevImageAnimatedStyle = useAnimatedStyle(() => ({
		transform: [{ scale: prevImageScale.get() }],
		opacity: prevImageScale.get()
	}))

	const nextImageAnimatedStyle = useAnimatedStyle(() => ({
		transform: [{ scale: nextImageScale.get() }],
		opacity: nextImageScale.get()
	}))

	const handleProfilePress = () => {
		router.push('/profile')
	}

	const handleHaptics = () => {
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
	}

	const switchToPreviousOrganization = () => {
		setCurrentOrganizationIndex(getWrappedIndex(-1))
	}

	const switchToNextOrganization = () => {
		setCurrentOrganizationIndex(getWrappedIndex(1))
	}

	const animateSwipeDown = () => {
		if (isAnimating.get()) return

		isAnimating.set(true)
		handleHaptics()

		profileImageTranslateY.set(withSpring(64, ANIMATION_SPRING_CONFIG))

		nextImageScale.set(
			withSpring(1, ANIMATION_SPRING_CONFIG, () => {
				if (currentOrganization === nextOrganization) return
				runOnJS(switchToNextOrganization)()
			})
		)
	}

	const animateSwipeUp = () => {
		if (isAnimating.get()) return

		isAnimating.set(true)
		handleHaptics()

		profileImageTranslateY.set(withSpring(-64, ANIMATION_SPRING_CONFIG))

		prevImageScale.set(
			withSpring(1, ANIMATION_SPRING_CONFIG, () => {
				if (currentOrganization === prevOrganization) return
				runOnJS(switchToPreviousOrganization)()
			})
		)
	}

	const animateSwipe = (direction: 'up' | 'down') => {
		if (isAnimating.get()) return

		isAnimating.set(true)
		handleHaptics()

		if (direction === 'up') {
			animateSwipeUp()
		} else {
			animateSwipeDown()
		}
	}

	const panGesture = Gesture.Pan().onEnd((event) => {
		const { velocityY, translationY } = event
		if (isAnimating.get() || hasOnlyOneOrganization) return

		if (Math.abs(velocityY) > 500 || Math.abs(translationY) > 50) {
			if (velocityY < 0 || translationY < 0) {
				runOnJS(animateSwipe)('up')
			} else {
				runOnJS(animateSwipe)('down')
			}
		}
	})

	const backgroundFadeStyle = useAnimatedStyle(() => {
		const backgroundColor = colors[theme].gray[75]
		return {
			backgroundColor: interpolateColor(
				backgroundAnimation.get(),
				[0, 1],
				[`${backgroundColor}ff`, `${backgroundColor}00`]
			)
		}
	})

	return (
		<Animated.View style={[styles.headerRight, backgroundFadeStyle]}>
			<GestureDetector gesture={panGesture}>
				<View style={styles.headerRightOrganizationContainer}>
					<TouchableOpacity
						style={[
							StyleSheet.absoluteFillObject,
							styles.headerRightProfileButton
						]}
						onPress={handleProfilePress}
					>
						<Animated.View
							style={[
								StyleSheet.absoluteFillObject,
								styles.headerRightAnimatedContainer,
								currentImageAnimatedStyle
							]}
						>
							<MotiView
								from={{ opacity: 0 }}
								animate={{ opacity: isShining ? 0 : 1 }}
								transition={{
									type: 'timing',
									duration: APPEAR_DURATION
								}}
								style={styles.headerRightMotiContainer}
							>
								<Image
									key={`current-${currentOrganization.id}`}
									source={
										currentOrganization.logoUrl ?? {
											blurhash: getBlurhashFromUUID(currentOrganization.id)
										}
									}
									placeholder={{
										blurhash: getBlurhashFromUUID(currentOrganization.id)
									}}
									style={styles.headerRightImage}
								/>
								<Text style={styles.headerRightAppearingInitial}>
									{currentOrganization.name.slice(0, 1)}
								</Text>
							</MotiView>
						</Animated.View>
					</TouchableOpacity>
					<AppearingImageContainer
						animatedStyle={prevImageAnimatedStyle}
						organization={prevOrganization}
					/>
					<AppearingImageContainer
						animatedStyle={nextImageAnimatedStyle}
						organization={nextOrganization}
					/>
				</View>
			</GestureDetector>
		</Animated.View>
	)
}

const styles = defineStyles({
	headerRight: {
		width: 44,
		height: 44,
		borderRadius: 50,
		justifyContent: 'center',
		alignItems: 'center',
		overflow: 'hidden'
	},
	headerRightOrganizationContainer: {
		width: '100%',
		height: '100%',
		justifyContent: 'center',
		alignItems: 'center'
	},
	headerRightProfileButton: {
		borderRadius: 50,
		justifyContent: 'center',
		alignItems: 'center'
	},
	headerRightAnimatedContainer: {
		justifyContent: 'center',
		alignItems: 'center'
	},
	headerRightMotiContainer: {
		justifyContent: 'center',
		alignItems: 'center',
		width: '75%',
		height: '75%'
	},
	headerRightAppearingContainer: {
		position: 'absolute',
		width: '75%',
		height: '75%'
	},
	headerRightImage: {
		width: '100%',
		height: '100%',
		borderRadius: 50,
		position: 'absolute'
	},
	headerRightAppearingInitialContainer: {
		justifyContent: 'center',
		alignItems: 'center',
		width: '100%',
		height: '100%'
	},
	headerRightAppearingInitial: {
		fontSize: 16,
		fontWeight: '500',
		color: colors.light.gray[25]
	}
})
